import os
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeDocumentRequest
from azure.core.credentials import AzureKeyCredential

def validate_invoice_fields(invoice_document_path: str) -> dict:
    """
    Validates required structured fields and confidence scores from an invoice using Azure Document Intelligence.

    Args:
        invoice_document_path (str): The path to the invoice document (image or PDF).

    Returns:
        dict: A dictionary containing the validation results, including extracted fields
              and their confidence scores. Returns None if analysis fails or no invoice is found.
    """
    endpoint = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint or not key:
        raise ValueError("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_KEY environment variables must be set.")

    document_intelligence_client = DocumentIntelligenceClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    with open(invoice_document_path, "rb") as f:
        document_data = f.read()

    poller = document_intelligence_client.begin_analyze_document(
        "prebuilt-invoice",
        AnalyzeDocumentRequest(bytes_base64=document_data),
    )
    result = poller.result()

    if result.documents:
        invoice = result.documents[0]
        extracted_data = {}

        # Example of extracting and validating common invoice fields
        required_fields = {
            "VendorName": None,
            "InvoiceId": None,
            "InvoiceDate": None,
            "TotalTax": None,
            "TotalDue": None,
        }

        for field_name in required_fields:
            field = invoice.fields.get(field_name)
            if field and field.value is not None:
                extracted_data[field_name] = {
                    "value": field.value.as_dict() if hasattr(field.value, 'as_dict') else field.value, # Handle different value types
                    "confidence": field.confidence
                }
            else:
                extracted_data[field_name] = {
                    "value": None,
                    "confidence": 0.0
                }
        return extracted_data
    return {}
